import base64,hashlib,json,sys,zlib
sys.dont_write_bytecode=True
z=base64.b64decode('',validate=True)
d=zlib.decompressobj(16+zlib.MAX_WBITS);r=d.decompress(z,262145)
assert len(r)<=262144 and d.eof and not d.unconsumed_tail and not d.unused_data
p=json.loads(r);assert set(p)=={'source_b64','plan_b64'}
s=base64.b64decode(p['source_b64'],validate=True);b=base64.b64decode(p['plan_b64'],validate=True)
assert len(s)==22313 and hashlib.sha256(s).hexdigest()=='3e72353d8bd0dec122f10f5f3f5a6fe50e6dfb5251a41e51fc89974d4d4867bb'
assert len(b)==2663 and hashlib.sha256(b).hexdigest()=='ffae67b5eb7548dc8e2677c0c508f1eea4fb571eff97976ca68795404df83d7b'
sys.argv=['capture_non_native_attempt05.py','--source-sha256','3e72353d8bd0dec122f10f5f3f5a6fe50e6dfb5251a41e51fc89974d4d4867bb','--plan-sha256','ffae67b5eb7548dc8e2677c0c508f1eea4fb571eff97976ca68795404df83d7b','--execute-readonly-capture-once']
exec(compile(s,'<reviewed-attempt05-non-native-capture>','exec'),{'__name__':'__main__','__file__':'<reviewed-attempt05-non-native-capture>','__capture_source_original__':s,'__capture_plan_original__':b})
